effect.shader:
void main(){
    vec4 src=texture2DCv(inputImg.texture, acScreenNorm);
    float h=dot(src.rgb, vec3(0.299,0.587,0.114));
    float sep=(h-0.5)*depth*0.04;
    float r=texture2DCv(inputImg.texture, acScreenNorm-vec2(sep,0.0)).r;
    vec4 cy=texture2DCv(inputImg.texture, acScreenNorm+vec2(sep,0.0));
    gl_FragColor=vec4(r, cy.g, cy.b, src.a);
}
